"""R10: pasos intermedios de fracciones y factorización. Ejemplos propios.
Conserva las unidades anteriores: cada habilidad nueva tiene un ID nuevo.
"""
import json,math,re
from pathlib import Path
from fractions import Fraction
U=[]
def activity(q,correct,steps,wrong):
 correct=str(correct);options=list(dict.fromkeys([correct,*map(str,wrong)]));assert len(options)>=2
 return dict(enunciado=q,respuesta_correcta=correct,opciones=options,paso_resuelto=steps,visual=None)
def unit(id,tema,after,title,explanation,example,steps,hint,rows,visual=None):
 assert len(rows)==6
 for i,r in enumerate(rows):
  r['id']=id+'-v'+str(i+1);k=i%len(r['opciones']);r['opciones']=r['opciones'][k:]+r['opciones'][:k]
  if id in ['prof_frac_comparar_denominador','prof_frac_comparar_numerador','prof_op_comparar']:
   pares=re.findall(r'(\d+)/(\d+)',r['enunciado']);r['visual']=[dict(label=f'{n}/{d}',partes=[1]*int(d),pintadas=int(n)) for n,d in pares]
 U.append(dict(id=id,tema=tema,despues_de=after,titulo=title,explicacion=explanation,ejemplo=example,pasos=steps,pista=hint,visual=visual,actividades=rows))
def bar(label,d,n):return dict(label=label,partes=[1]*d,pintadas=n)
t='fracciones_concepto'
unit('prof_frac_amplificar',t,'frac_con_4_equivalencias_visuales','Más cortes, la misma cantidad','Amplificar es multiplicar el numerador y el denominador por el mismo natural distinto de cero. Cambian los cortes y las partes contadas, pero no la cantidad del entero que tomamos. No alcanza con multiplicar solo arriba.','2/3 = 4/6: multiplicamos arriba y abajo por 2.',['Cada tercio se divide en dos partes: ahora hay 6 sextos.','Los 2 tercios ocupan 4 sextos: (2 × 2)/(3 × 2) = 4/6.'],'Usá el mismo factor arriba y abajo.',[activity(f'Amplificá {n}/{d} multiplicando numerador y denominador por {k}.',f'{n*k}/{d*k}',f'Arriba: {n} × {k} = {n*k}.\nAbajo: {d} × {k} = {d*k}. La fracción es {n*k}/{d*k}.',[f'{n*k}/{d}',f'{n}/{d*k}']) for n,d,k in [(2,3,2),(1,4,3),(3,5,2),(2,7,3),(3,4,4),(4,5,3)]],[bar('Antes: 2/3',3,2),bar('Después: 4/6',6,4)])
unit('prof_frac_simplificar',t,'prof_frac_amplificar','Menos cortes, la misma cantidad','Simplificar es dividir numerador y denominador por un mismo divisor mayor que uno. La cantidad representada no cambia. Si ya no tienen divisores comunes mayores que uno, la fracción es irreducible.','6/8 = 3/4: dividimos arriba y abajo por 2.',['6 ÷ 2 = 3 y 8 ÷ 2 = 4.','3 y 4 no comparten un divisor mayor que 1: terminamos.'],'Buscá un número que divida exactamente arriba y abajo.',[activity(f'Simplificá {n}/{d} dividiendo numerador y denominador por {k}.',f'{n//k}/{d//k}',f'{n} ÷ {k} = {n//k}; {d} ÷ {k} = {d//k}.\nQueda {n//k}/{d//k}, con el mismo valor.',[f'{n//k}/{d}',f'{n}/{d//k}']) for n,d,k in [(6,8,2),(4,10,2),(9,12,3),(10,15,5),(12,20,4),(14,21,7)]],[bar('6/8',8,6),bar('3/4',4,3)])
unit('prof_frac_comparar_denominador',t,'prof_frac_simplificar','Comparar partes del mismo tamaño','Si las fracciones tienen el mismo denominador y se refieren al mismo entero, sus partes tienen el mismo tamaño. Es mayor la que toma más partes: la de numerador mayor.','3/5 es mayor que 2/5.',['Ambas cuentan quintos del mismo entero.','Tres quintos ocupan más que dos quintos.'],'Con el mismo denominador, compará los numeradores.',[activity(f'Del mismo entero, ¿cuál es mayor: {a}/{d} o {b}/{d}?',f'{max(a,b)}/{d}',f'Las partes son del mismo tamaño. {max(a,b)} partes son más que {min(a,b)}.',[f'{min(a,b)}/{d}','Son iguales']) for a,b,d in [(3,2,5),(1,3,4),(4,2,7),(2,5,6),(5,3,8),(3,7,10)]],[bar('3/5',5,3),bar('2/5',5,2)])
unit('prof_frac_comparar_numerador',t,'prof_frac_comparar_denominador','Igual cantidad de partes, distinto tamaño','Cuando tomamos la misma cantidad de partes del mismo entero, importa el tamaño de cada parte. Si el entero se divide en más partes iguales, cada parte es más pequeña. Por eso 1/3 es mayor que 1/5.','2/3 es mayor que 2/5 del mismo entero.',['En ambos casos tomamos 2 partes.','Cada tercio es más grande que cada quinto. Dos tercios ocupan más.'],'Con igual numerador positivo, el denominador menor indica partes más grandes.',[activity(f'Del mismo entero, ¿cuál es mayor: {n}/{d} o {n}/{e}?',f'{n}/{min(d,e)}',f'Tomamos {n} partes en ambos casos. Las partes en {min(d,e)} son mayores que las partes en {max(d,e)}.',[f'{n}/{max(d,e)}','Son iguales']) for n,d,e in [(2,3,5),(1,6,4),(3,4,7),(2,8,5),(4,5,9),(3,10,8)]],[bar('2/3',3,2),bar('2/5',5,2)])
unit('prof_frac_clasificar',t,'prof_frac_comparar_numerador','Fracciones menores, mayores o iguales a enteros','En el cuadernillo, una fracción propia tiene numerador menor que el denominador. Es aparente si el numerador es múltiplo del denominador: representa un entero. Si el numerador es mayor y no es múltiplo, la llamamos impropia.','3/4 es propia; 5/4 es impropia; 8/4 es aparente.',['Primero comprobamos si representa un entero: 8 ÷ 4 = 2.','Si no, comparamos arriba y abajo: 3 < 4 y 5 > 4.'],'Primero fijate si la división es exacta; después compará arriba y abajo.',[activity(f'Según la clasificación del cuadernillo, ¿qué tipo de fracción es {n}/{d}?',c,why,['propia','impropia','aparente']) for n,d,c,why in [(3,4,'propia','3 < 4: representa menos de un entero.'),(7,5,'impropia','7 > 5 y 7 no es múltiplo de 5.'),(12,4,'aparente','12 ÷ 4 = 3: representa tres enteros.'),(5,8,'propia','5 < 8: representa menos de un entero.'),(11,6,'impropia','11 > 6 y 11 no es múltiplo de 6.'),(9,9,'aparente','9 ÷ 9 = 1: representa un entero.')]])
unit('prof_frac_a_mixto',t,'prof_frac_clasificar','Agrupar partes para formar enteros','Un número mixto escribe por separado los enteros y la fracción que sobra. En 7/4, cada grupo de cuatro cuartos forma un entero. Podemos dividir 7 entre 4: cociente 1 y resto 3.','7/4 = 1 3/4, que significa 1 + 3/4.',['Agrupamos 4 de los 7 cuartos: forman 1 entero.','Sobran 3 cuartos: escribimos 1 3/4.'],'Cada grupo del tamaño del denominador forma un entero.',[activity(f'Escribí {n}/{d} como número mixto.',f'{n//d} {n%d}/{d}',f'{n} ÷ {d}: cociente {n//d}, resto {n%d}.\nSon {n//d} enteros y {n%d}/{d}.',[f'{n%d} {n//d}/{d}',f'{n//d} {n%d}/{n}']) for n,d in [(7,4),(8,3),(11,4),(13,5),(17,6),(19,8)]],[bar('Un entero: 4/4',4,4),bar('Lo que sobra: 3/4',4,3)])
unit('prof_frac_desde_mixto',t,'prof_frac_a_mixto','Contar todas las partes de un mixto','Para convertir un mixto en una fracción, contamos las partes de sus enteros y sumamos las que sobran. Conservamos el denominador: las partes siguen teniendo el mismo tamaño.','2 1/3 = 7/3.',['Dos enteros contienen 2 × 3 = 6 tercios.','Sumamos el tercio que sobra: 6 + 1 = 7 tercios.'],'Multiplicá los enteros por el denominador y sumá el numerador.',[activity(f'Convertí el número mixto {w} {n}/{d} en una fracción.',f'{w*d+n}/{d}',f'{w} enteros contienen {w} × {d} = {w*d} partes.\n{w*d} + {n} = {w*d+n}: queda {w*d+n}/{d}.',[f'{w+n}/{d}',f'{w*d}/{d+n}']) for w,n,d in [(2,1,3),(1,3,4),(3,2,5),(2,3,7),(4,1,6),(3,5,8)]])
def factors(n):
 out=[];p=2
 while n>1:
  while n%p==0:out.append(p);n//=p
  p+=1
 return out
def product(xs):return ' × '.join(map(str,xs))
t='divisibilidad_primos_mcm_mcd'
unit('prof_fact_primos',t,'div_primos_3_primos_compuestos','Desarmar un número en factores primos','Factorizar en primos es escribir un número mayor que uno como una multiplicación de números primos. Podemos dividirlo por primos hasta llegar a 1. Comprobamos multiplicando todos los factores.','12 = 2 × 2 × 3.',['12 ÷ 2 = 6; 6 ÷ 2 = 3; 3 ÷ 3 = 1.','Los divisores usados son 2, 2 y 3. Su producto vuelve a dar 12.'],'Todos los factores deben ser primos y su producto debe dar el número original.',[activity(f'¿Cuál es la descomposición de {n} en factores primos?',product(factors(n)),f'Dividimos sucesivamente por primos: {product(factors(n))}.\nSu producto es {n}; cada factor es primo.',[f'{n} × 1',f'{n//2} × 2',product(factors(n)+[2])]) for n in [12,18,20,28,30,45]])
unit('prof_fact_mcm',t,'prof_fact_primos','MCM: reunir los factores necesarios','El MCM positivo puede construirse con factores primos. Tomamos cada primo que aparezca en cualquiera de los números, repetido la mayor cantidad de veces que aparezca en uno de ellos. Así el resultado contiene los factores necesarios para ambos.','12 = 2 × 2 × 3 y 18 = 2 × 3 × 3. Su MCM es 36.',['Necesitamos dos factores 2 y dos factores 3.','2 × 2 × 3 × 3 = 36. Tanto 12 como 18 dividen exactamente a 36.'],'Para el MCM conservá cada primo con la mayor cantidad de repeticiones.',[activity(f'{x} = {product(factors(x))}; {y} = {product(factors(y))}. ¿Cuál es el MCM de {x} y {y}?',math.lcm(x,y),f'Reunimos cada primo con la mayor cantidad de repeticiones: {product(factors(math.lcm(x,y)))}.\nSu producto es {math.lcm(x,y)}.',[math.gcd(x,y),x*y,x+y]) for x,y in [(12,18),(8,12),(10,15),(18,24),(20,30),(14,21)]])
unit('prof_fact_mcd',t,'div_primos_5_mcd','MCD: conservar solo lo que comparten','Para construir el MCD con factores primos, tomamos solamente los primos que aparecen en ambos números. Conservamos la menor cantidad de repeticiones compartida. Si no comparten ningún primo, su MCD es 1.','12 = 2 × 2 × 3 y 18 = 2 × 3 × 3. Su MCD es 6.',['Ambos tienen al menos un factor 2 y un factor 3.','Conservamos uno de cada: 2 × 3 = 6.'],'Para el MCD buscá lo común, con la menor cantidad de repeticiones.',[activity(f'{x} = {product(factors(x))}; {y} = {product(factors(y))}. ¿Cuál es el MCD de {x} y {y}?',math.gcd(x,y),(f'Comparten {product(factors(math.gcd(x,y)))}.\nEl producto es {math.gcd(x,y)}.' if math.gcd(x,y)>1 else 'No comparten factores primos. Su único divisor común es 1.'),[math.lcm(x,y),x+y,min(x,y)]) for x,y in [(12,18),(16,24),(18,30),(20,28),(14,25),(27,36)]])
t='fracciones_operaciones'
unit('prof_op_preparar',t,'frac_op_1_igual_denominador','Preparar partes del mismo tamaño','Antes de sumar fracciones con denominadores distintos, las expresamos en partes iguales. El MCM de los denominadores nos sirve como denominador común. Para cambiar una fracción, multiplicamos arriba y abajo por el mismo factor.','Para tercios y cuartos usamos doceavos: 2/3 = 8/12.',['El MCM de 3 y 4 es 12. Para pasar de 3 a 12 multiplicamos por 4.','Multiplicamos también arriba: 2 × 4 = 8. Queda 8/12.'],'Dividí el denominador nuevo por el anterior para encontrar el factor.',[activity(f'Vamos a usar denominador {c}. ¿Cómo queda {n}/{d} al amplificarla hasta ese denominador?',f'{n*(c//d)}/{c}',f'{c} ÷ {d} = {c//d}: ese es el factor.\n{n} × {c//d} = {n*(c//d)}; queda {n*(c//d)}/{c}.',[f'{n}/{c}',f'{n+(c//d)}/{c}']) for n,d,c in [(2,3,12),(3,4,12),(1,6,18),(4,5,20),(5,6,24),(2,7,21)]])
unit('prof_op_comparar',t,'prof_op_preparar','Comparar con un denominador común','Para comparar dos fracciones, primero las expresamos con el mismo denominador. Después comparamos cuántas partes tomamos. Deben referirse al mismo entero.','2/3 es menor que 3/4.',['El denominador común es 12: 2/3 = 8/12 y 3/4 = 9/12.','8 < 9: dos tercios es menor que tres cuartos.'],'Convertí las dos fracciones antes de comparar sus numeradores.',[activity(f'Del mismo entero, ¿cuál es mayor: {a}/{b} o {c}/{d}?',f'{a}/{b}' if Fraction(a,b)>Fraction(c,d) else f'{c}/{d}',f'Usamos denominador {math.lcm(b,d)}: {a*math.lcm(b,d)//b}/{math.lcm(b,d)} y {c*math.lcm(b,d)//d}/{math.lcm(b,d)}.\nLa que tiene numerador mayor representa más.',[f'{c}/{d}' if Fraction(a,b)>Fraction(c,d) else f'{a}/{b}','Son iguales']) for a,b,c,d in [(2,3,3,4),(3,5,1,2),(5,6,4,5),(2,7,1,3),(3,8,2,5),(4,9,5,12)]],[bar('2/3',3,2),bar('3/4',4,3)])
unit('prof_op_restar',t,'frac_op_2_distinto_denominador','Restar fracciones de distinto denominador','Para restar fracciones, necesitamos partes del mismo tamaño. Las convertimos al denominador común, restamos los numeradores y conservamos ese denominador. Después simplificamos si podemos.','5/6 − 1/4 = 7/12.',['MCM de 6 y 4: 12. Convertimos 5/6 = 10/12 y 1/4 = 3/12.','Restamos: (10 − 3)/12 = 7/12.'],'No restes los denominadores: primero igualá el tamaño de las partes.',[activity(f'Resolvé {a}/{b} − {c}/{d}.',str(Fraction(a,b)-Fraction(c,d)),f'Con denominador {math.lcm(b,d)}, queda {a*math.lcm(b,d)//b}/{math.lcm(b,d)} − {c*math.lcm(b,d)//d}/{math.lcm(b,d)}.\nRestamos numeradores y simplificamos: {Fraction(a,b)-Fraction(c,d)}.',[str(Fraction(a,b)+Fraction(c,d)),f'{a+c}/{b+d}']) for a,b,c,d in [(5,6,1,4),(3,4,1,3),(4,5,1,2),(7,8,1,4),(5,6,1,3),(8,9,1,6)]])
unit('prof_op_dividir_medida',t,'frac_op_4_multiplicacion','Dividir también pregunta cuántas partes caben','Dividir una cantidad por una fracción puede preguntar cuántas porciones de ese tamaño caben. Si un litro llena cuatro vasos de 1/4 de litro, dos litros llenan ocho. Dividir no siempre da un número menor.','2 litros ÷ 1/4 de litro por vaso = 8 vasos.',['En cada litro caben 4 vasos de un cuarto.','En 2 litros caben 2 × 4 = 8 vasos.'],'Contá cuántas porciones caben en un entero y después en todos los enteros.',[activity(f'Tenés {n} litros. Cada vaso contiene 1/{d} de litro. ¿Cuántos vasos completos podés llenar?',n*d,f'Cada litro llena {d} vasos.\n{n} litros llenan {n} × {d} = {n*d} vasos.',[n+d,n]) for n,d in [(2,4),(3,2),(2,3),(4,5),(3,4),(5,2)]],[bar('Un litro',4,4),bar('Otro litro',4,4)])
root=Path(__file__).resolve().parents[1];p=root/'src/lib/contenido-bases.js';s=p.read_text(encoding='utf-8')
start='// R10: pasos intermedios.';end='// FIN R10'
if start in s:s=s[:s.index(start)]+s[s.index(end)+len(end):]
code=start+'\nconst PROFUNDIZACION = '+json.dumps(U,ensure_ascii=False,indent=2)+''';
for (const unidad of PROFUNDIZACION) {
 const indice = UNIDADES_BASES.findIndex(u => u.id === unidad.despues_de);
 if (indice < 0) throw new Error('Falta el paso anterior de ' + unidad.id);
 UNIDADES_BASES.splice(indice + 1, 0, unidad);
}
'''+end+'\n\n'
i=min(s.index(m) for m in ['// R11: decimales paso a paso.','// R12: medidas paso a paso.','// R13: geometria con diagramas.','// R14: figuras y superficies.','// R15: problemas por etapas.','export const TEMAS_BASES'] if m in s);s=s[:i]+code+s[i:];p.write_text(s,encoding='utf-8')
print(len(U),'unidades nuevas;',len(U)*6,'actividades')
